node --input-type=module - <<'JS'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { importStock } from './src/entry.js';
const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['files', 'output', 'invalid_numeric', 'reserved_applied_before_clamp']);
const pipeline = [
  ['src/entry.js', 'importStock'],
  ['src/input/csv.js', 'parseStock'],
  ['src/domain/stock.js', 'normalizeStock'],
  ['src/domain/sku.js', 'canonicalSku'],
  ['src/output/wire.js', 'wireStock'],
];
assert.deepEqual(answer.files, pipeline.map(([path]) => path));
for (const [path, symbol] of pipeline) assert.equal(typeof (await import(`./${path}`))[symbol], 'function');
assert.deepEqual(answer.output, importStock(' ab-2 ,5,8'));
assert.throws(() => importStock('x,no,1'), error => error.message === answer.invalid_numeric);
assert.equal(answer.reserved_applied_before_clamp, true);
assert.deepEqual(importStock('x,-3,-2'), {product_code: 'X', units: 0, schema: 2});
console.log('PASS: answer schema, pipeline exports, example, error, and subtraction before clamp');
